def determine_winner(s):
    n = len(s)
    result = []

    for k in range(n):
        l, r = k, k
        while l > 0 and s[l - 1] < s[l]:
            l -= 1
        while r + 1 < n and s[r + 1] < s[r]:
            r += 1

        if (r - l + 1) % 2 == 0:
            result.append("Mike")
        else:
            result.append("Ann")

    return result

